public boolean canArrange(int[] arr, int k) {
    if (arr == null || k <= 0 || arr.length % 2 != 0) {
        return false;
    }
    int n = arr.length;
    int[] freq = new int[k];
    for (int num : arr) {
        int r = ((num % k) + k) % k;
        freq[r]++;
    }
    // Check remainder 0
    if (freq[0] % 2 != 0) {
        return false;
    }
    // Check other remainders
    for (int r = 1; r <= k / 2; r++) {
        int complement = k - r;
        if (r == complement) { // when k is even and r == k/2
            if (freq[r] % 2 != 0) {
                return false;
            }
        } else {
            if (freq[r] != freq[complement]) {
                return false;
            }
        }
    }
    return true;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    if (n <= 0 || edges == null || hasApple == null || hasApple.length != n) {
        throw new IllegalArgumentException("Invalid input");
    }
    if (edges.length != n - 1) {
        throw new IllegalArgumentException("Edges length must be n-1");
    }
    java.util.List<Integer>[] graph = new java.util.ArrayList[n];
    for (int i = 0; i < n; i++) {
        graph[i] = new java.util.ArrayList<>();
    }
    for (int[] e : edges) {
        if (e == null || e.length != 2) {
            throw new IllegalArgumentException("Each edge must have two nodes");
        }
        int u = e[0], v = e[1];
        if (u < 0 || u >= n || v < 0 || v >= n) {
            throw new IllegalArgumentException("Edge node out of bounds");
        }
        graph[u].add(v);
        graph[v].add(u);
    }
    int[] time = new int[1];
    dfs(0, -1, graph, hasApple, time);
    return time[0];
}

private boolean dfs(int node, int parent, java.util.List<Integer>[] graph, boolean[] hasApple, int[] time) {
    boolean has = hasApple[node];
    for (int nei : graph[node]) {
        if (nei == parent) continue;
        boolean childHas = dfs(nei, node, graph, hasApple, time);
        if (childHas) {
            time[0] += 2;
            has = true;
        }
    }
    return has;
}

public String sortString(String s) {
    if (s == null || s.isEmpty()) {
        return "";
    }
    // Count occurrences of each lowercase letter
    int[] count = new int[26];
    for (char c : s.toCharArray()) {
        if (c < 'a' || c > 'z') {
            throw new IllegalArgumentException("Input string must contain only lowercase letters");
        }
        count[c - 'a']++;
    }
    StringBuilder result = new StringBuilder(s.length());
    int remaining = s.length();
    while (remaining > 0) {
        // Ascending pass: pick smallest to largest
        for (int i = 0; i < 26 && remaining > 0; i++) {
            if (count[i] > 0) {
                result.append((char) ('a' + i));
                count[i]--;
                remaining--;
            }
        }
        // Descending pass: pick largest to smallest
        for (int i = 25; i >= 0 && remaining > 0; i--) {
            if (count[i] > 0) {
                result.append((char) ('a' + i));
                count[i]--;
                remaining--;
            }
        }
    }
    return result.toString();
}

public boolean splitArraySameAverage(int[] nums) {
    if (nums == null || nums.length < 2) {
        return false;
    }
    int n = nums.length;
    int totalSum = 0;
    for (int num : nums) {
        totalSum += num;
    }
    // Use DP sets for subset sums by size
    @SuppressWarnings("unchecked")
    java.util.HashSet<Integer>[] sumsBySize = new java.util.HashSet[n + 1];
    for (int i = 0; i <= n; i++) {
        sumsBySize[i] = new java.util.HashSet<>();
    }
    sumsBySize[0].add(0);
    for (int num : nums) {
        // iterate sizes in reverse to avoid using the same element twice
        for (int size = n - 1; size >= 0; size--) {
            if (sumsBySize[size].isEmpty()) continue;
            for (int s : sumsBySize[size]) {
                sumsBySize[size + 1].add(s + num);
            }
        }
    }
    // Check for any valid split
    for (int k = 1; k <= n / 2; k++) {
        if ((totalSum * k) % n != 0) continue;
        int target = (totalSum * k) / n;
        if (sumsBySize[k].contains(target)) {
            return true;
        }
    }
    return false;
}

public int minCostClimbingStairs(int[] cost) {
    // Handle null or empty input gracefully
    if (cost == null || cost.length == 0) {
        return 0;
    }

    int n = cost.length;
    // dp0 represents min cost to reach step i-2, dp1 to reach step i-1
    int dp0 = 0; // cost to reach step -1 (virtual start)
    int dp1 = 0; // cost to reach step 0

    for (int i = 2; i <= n; i++) {
        // cost to reach step i is min of stepping from i-1 or i-2
        int costFromPrev = dp1 + cost[i - 1];
        int costFromPrevPrev = dp0 + cost[i - 2];
        int current = Math.min(costFromPrev, costFromPrevPrev);

        // shift for next iteration
        dp0 = dp1;
        dp1 = current;
    }

    // dp1 now holds min cost to reach the top (step n)
    return dp1;
}

public int uniqueMorseRepresentations(String[] words) {
    if (words == null) {
        return 0;
    }
    String[] morse = {".-","-...","-.-.","-..",".","..-.","--.","....","..",
                      ".---","-.-",".-..","--","-.","---",".--.","--.-",".-.",
                      "...","-","..-","...-",".--","-..-","-.--","--.."};
    java.util.Set<String> set = new java.util.HashSet<>();
    for (String word : words) {
        if (word == null) {
            continue;
        }
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < word.length(); i++) {
            char c = word.charAt(i);
            if (c >= 'a' && c <= 'z') {
                sb.append(morse[c - 'a']);
            } else if (c >= 'A' && c <= 'Z') {
                sb.append(morse[c - 'A']);
            } // ignore non-letter characters
        }
        set.add(sb.toString());
    }
    return set.size();
}

public boolean hasAllCodes(String s, int k) {
    if (s == null || k <= 0) {
        return false;
    }
    int n = s.length();
    // If k is too large, 2^k will exceed possible substrings
    if (k > 20) { // 2^20 = 1,048,576 > typical string lengths
        return false;
    }
    int total = 1 << k;
    if (n < total) {
        return false;
    }
    int mask = total - 1;
    boolean[] seen = new boolean[total];
    int count = 0;
    int curr = 0;
    for (int i = 0; i < n; i++) {
        char c = s.charAt(i);
        if (c != '0' && c != '1') {
            return false; // invalid character
        }
        curr = ((curr << 1) & mask) | (c - '0');
        if (i >= k - 1) {
            if (!seen[curr]) {
                seen[curr] = true;
                count++;
                if (count == total) {
                    return true;
                }
            }
        }
    }
    return false;
}

