public int minInsertions(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }
    int balance = 0; // number of unmatched '('
    int insertions = 0; // number of insertions needed
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '(') {
            balance++;
        } else if (c == ')') {
            if (balance > 0) {
                balance--; // match with a previous '('
            } else {
                // need an extra '(' before this ')'
                insertions++;
                // balance remains 0 after using the inserted '('
            }
        } else {
            // invalid character encountered; ignore or handle as needed
            // For robustness, we can skip or throw an exception
            // Here we simply ignore it
        }
    }
    // any remaining unmatched '(' need ')' inserted
    insertions += balance;
    return insertions;
}

