public int maxAbsoluteSum(int[] nums) {
    if (nums == null || nums.length == 0) {
        return 0;
    }
    long maxSum = Long.MIN_VALUE;
    long minSum = Long.MAX_VALUE;
    long currentMax = 0;
    long currentMin = 0;
    for (int num : nums) {
        currentMax = Math.max(num, currentMax + num);
        maxSum = Math.max(maxSum, currentMax);
        currentMin = Math.min(num, currentMin + num);
        minSum = Math.min(minSum, currentMin);
    }
    long result = Math.max(maxSum, -minSum);
    // Clamp to int range if necessary
    if (result > Integer.MAX_VALUE) {
        return Integer.MAX_VALUE;
    }
    if (result < Integer.MIN_VALUE) {
        return Integer.MIN_VALUE;
    }
    return (int) result;
}

public int findMinFibonacciNumbers(int k) {
    if (k <= 0) {
        throw new IllegalArgumentException("k must be positive");
    }
    // Generate Fibonacci numbers up to k
    int[] fib = new int[50]; // 50 is enough for int range
    int size = 0;
    fib[size++] = 1;
    fib[size++] = 1;
    while (true) {
        long next = (long) fib[size - 1] + fib[size - 2];
        if (next > k) {
            break;
        }
        fib[size++] = (int) next;
    }
    // Greedy selection from largest to smallest
    int count = 0;
    int remaining = k;
    for (int i = size - 1; i >= 0; i--) {
        if (fib[i] <= remaining) {
            remaining -= fib[i];
            count++;
        }
        if (remaining == 0) {
            break;
        }
    }
    return count;
}

public int kthFactor(int n, int k) {
    if (n <= 0 || k <= 0) {
        return -1;
    }
    java.util.ArrayList<Integer> small = new java.util.ArrayList<>();
    java.util.ArrayList<Integer> large = new java.util.ArrayList<>();
    int sqrtN = (int) Math.sqrt(n);
    for (int i = 1; i <= sqrtN; i++) {
        if (n % i == 0) {
            small.add(i);
            int other = n / i;
            if (other != i) {
                large.add(other);
            }
        }
    }
    java.util.Collections.reverse(large);
    int totalFactors = small.size() + large.size();
    if (k > totalFactors) {
        return -1;
    }
    if (k <= small.size()) {
        return small.get(k - 1);
    } else {
        return large.get(k - small.size() - 1);
    }
}

public String makeGood(String s) {
    if (s == null) {
        return null;
    }
    StringBuilder stack = new StringBuilder();
    for (char c : s.toCharArray()) {
        int len = stack.length();
        if (len > 0) {
            char last = stack.charAt(len - 1);
            // Check if last and current are the same letter but opposite case
            if (last != c && Character.toLowerCase(last) == Character.toLowerCase(c)) {
                stack.deleteCharAt(len - 1);
                continue;
            }
        }
        stack.append(c);
    }
    return stack.toString();
}

public int maxUniqueSplit(String s) {
    if (s == null) return 0;
    int n = s.length();
    if (n == 0) return 0;
    class Solver {
        int dfs(int pos, java.util.Set<String> used) {
            if (pos == n) return 0;
            int best = 0;
            for (int i = pos + 1; i <= n; i++) {
                String sub = s.substring(pos, i);
                if (!used.contains(sub)) {
                    used.add(sub);
                    int res = 1 + dfs(i, used);
                    if (res > best) best = res;
                    used.remove(sub);
                }
            }
            return best;
        }
    }
    Solver solver = new Solver();
    return solver.dfs(0, new java.util.HashSet<>());
}

