public static int singleNumber(int[] nums) {
    if (nums == null || nums.length == 0) {
        throw new IllegalArgumentException("Input array must not be null or empty");
    }
    int result = 0;
    for (int i = 0; i < 32; i++) {
        int bitCount = 0;
        for (int num : nums) {
            if (((num >> i) & 1) == 1) {
                bitCount++;
            }
        }
        if ((bitCount % 3) != 0) {
            result |= (1 << i);
        }
    }
    return result;
}

public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new ArrayList<>();
    if (high < 0) {
        return result;
    }
    if (low < 0) {
        low = 0;
    }
    // Handle 0 separately
    if (low <= 0 && 0 <= high) {
        result.add(0);
    }
    // Use BFS to generate stepping numbers starting from 1 to 9
    ArrayDeque<Long> queue = new ArrayDeque<>();
    for (int i = 1; i <= 9; i++) {
        if (i <= high) {
            queue.offer((long) i);
        }
    }
    while (!queue.isEmpty()) {
        long num = queue.poll();
        if (num >= low && num <= high) {
            result.add((int) num);
        }
        if (num > high) {
            continue;
        }
        int lastDigit = (int) (num % 10);
        // Next possible digits
        if (lastDigit > 0) {
            long nextNum = num * 10 + (lastDigit - 1);
            if (nextNum <= high) {
                queue.offer(nextNum);
            }
        }
        if (lastDigit < 9) {
            long nextNum = num * 10 + (lastDigit + 1);
            if (nextNum <= high) {
                queue.offer(nextNum);
            }
        }
    }
    Collections.sort(result);
    return result;
}

public static int countDigitOne(int n) {
    if (n <= 0) {
        return 0;
    }
    long count = 0;
    long factor = 1;
    while (n / factor > 0) {
        long lower = n - (n / factor) * factor;
        long cur = (n / factor) % 10;
        long higher = n / (factor * 10);
        if (cur == 0) {
            count += higher * factor;
        } else if (cur == 1) {
            count += higher * factor + lower + 1;
        } else {
            count += (higher + 1) * factor;
        }
        factor *= 10;
    }
    return (int) count;
}

public static boolean isPowerOfTwo(int n) {
    // A power of two must be a positive integer.
    if (n <= 0) {
        return false;
    }
    // Using the property that a power of two has only one bit set.
    // For any positive integer n, n & (n - 1) == 0 iff n is a power of two.
    return (n & (n - 1)) == 0;
}

public static int addDigits(int num) {
    if (num < 0) {
        throw new IllegalArgumentException("Input must be a non-negative integer");
    }
    while (num >= 10) {
        int sum = 0;
        while (num > 0) {
            sum += num % 10;
            num /= 10;
        }
        num = sum;
    }
    return num;
}

public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0] == null || mat[0].length == 0) {
        return 0;
    }
    int m = mat.length;
    int n = mat[0].length;
    int[][] horizontal = new int[m][n];
    int[][] vertical = new int[m][n];
    int[][] diagonal = new int[m][n];
    int[][] antiDiagonal = new int[m][n];
    int maxLen = 0;
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                horizontal[i][j] = (j > 0 ? horizontal[i][j - 1] : 0) + 1;
                vertical[i][j] = (i > 0 ? vertical[i - 1][j] : 0) + 1;
                diagonal[i][j] = (i > 0 && j > 0 ? diagonal[i - 1][j - 1] : 0) + 1;
                antiDiagonal[i][j] = (i > 0 && j < n - 1 ? antiDiagonal[i - 1][j + 1] : 0) + 1;
                int currentMax = Math.max(Math.max(horizontal[i][j], vertical[i][j]),
                                          Math.max(diagonal[i][j], antiDiagonal[i][j]));
                if (currentMax > maxLen) {
                    maxLen = currentMax;
                }
            } else {
                horizontal[i][j] = 0;
                vertical[i][j] = 0;
                diagonal[i][j] = 0;
                antiDiagonal[i][j] = 0;
            }
        }
    }
    return maxLen;
}

public static String addThousandSeparator(int n) {
    // Handle zero explicitly
    if (n == 0) {
        return "0";
    }

    boolean negative = n < 0;
    // Work with absolute value to simplify processing
    int absValue = Math.abs(n);
    String numberStr = Integer.toString(absValue);

    StringBuilder sb = new StringBuilder();
    int count = 0;
    // Iterate from the end of the string to the beginning
    for (int i = numberStr.length() - 1; i >= 0; i--) {
        sb.append(numberStr.charAt(i));
        count++;
        // Insert dot after every three digits, but not at the start
        if (count == 3 && i > 0) {
            sb.append('.');
            count = 0;
        }
    }

    // Reverse to get the correct order
    sb.reverse();

    // Prepend negative sign if necessary
    if (negative) {
        sb.insert(0, '-');
    }

    return sb.toString();
}

public static int squarePermutations(int[] A) {
    int n = A.length;
    if (n == 0) return 0;
    // Precompute adjacency matrix
    boolean[][] can = new boolean[n][n];
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (i == j) continue;
            int sum = A[i] + A[j];
            int r = (int) Math.sqrt(sum);
            can[i][j] = r * r == sum;
        }
    }
    int fullMask = (1 << n) - 1;
    long[][] dp = new long[1 << n][n];
    for (int i = 0; i < n; i++) {
        dp[1 << i][i] = 1;
    }
    for (int mask = 1; mask <= fullMask; mask++) {
        for (int last = 0; last < n; last++) {
            long cur = dp[mask][last];
            if (cur == 0) continue;
            for (int next = 0; next < n; next++) {
                if ((mask & (1 << next)) != 0) continue;
                if (!can[last][next]) continue;
                dp[mask | (1 << next)][next] += cur;
            }
        }
    }
    long total = 0;
    for (int i = 0; i < n; i++) {
        total += dp[fullMask][i];
    }
    return (int) total;
}

public static int largestRectangleArea(int[] heights) {
    if (heights == null || heights.length == 0) {
        return 0;
    }
    int n = heights.length;
    int[] stack = new int[n];
    int top = -1;
    long maxArea = 0;
    int i = 0;
    try {
        while (i < n) {
            if (top == -1 || heights[i] >= heights[stack[top]]) {
                stack[++top] = i++;
            } else {
                int height = heights[stack[top--]];
                int width = (top == -1) ? i : i - stack[top] - 1;
                long area = (long) height * width;
                if (area > maxArea) {
                    maxArea = area;
                }
            }
        }
        while (top != -1) {
            int height = heights[stack[top--]];
            int width = (top == -1) ? i : i - stack[top] - 1;
            long area = (long) height * width;
            if (area > maxArea) {
                maxArea = area;
            }
        }
    } catch (Exception e) {
        return 0;
    }
    return (int) maxArea;
}

public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return new int[0];
    }
    int m = mat.length;
    int n = mat[0].length;
    int[] result = new int[m * n];
    int idx = 0;
    int totalDiagonals = m + n - 1;
    for (int s = 0; s < totalDiagonals; s++) {
        int row, col;
        if (s < n) {
            row = 0;
            col = s;
        } else {
            row = s - (n - 1);
            col = n - 1;
        }
        // Collect elements of this diagonal
        java.util.ArrayList<Integer> temp = new java.util.ArrayList<>();
        while (row < m && col >= 0) {
            temp.add(mat[row][col]);
            row++;
            col--;
        }
        // If diagonal index is even, reverse the order
        if (s % 2 == 0) {
            for (int i = temp.size() - 1; i >= 0; i--) {
                result[idx++] = temp.get(i);
            }
        } else {
            for (int i = 0; i < temp.size(); i++) {
                result[idx++] = temp.get(i);
            }
        }
    }
    return result;
}

public static int findSmallestInteger(int n) {
    if (n <= 0) {
        return -1;
    }
    char[] digits = String.valueOf(n).toCharArray();
    int len = digits.length;
    // Find the first index from the end where digits[i] < digits[i+1]
    int i = len - 2;
    while (i >= 0 && digits[i] >= digits[i + 1]) {
        i--;
    }
    if (i < 0) {
        // No higher permutation exists
        return -1;
    }
    // Find the smallest digit on right side of i that is greater than digits[i]
    int j = len - 1;
    while (j > i && digits[j] <= digits[i]) {
        j--;
    }
    // Swap digits[i] and digits[j]
    char temp = digits[i];
    digits[i] = digits[j];
    digits[j] = temp;
    // Reverse the suffix starting at i+1
    int left = i + 1;
    int right = len - 1;
    while (left < right) {
        temp = digits[left];
        digits[left] = digits[right];
        digits[right] = temp;
        left++;
        right--;
    }
    try {
        return Integer.parseInt(new String(digits));
    } catch (NumberFormatException e) {
        // In case the result exceeds integer bounds
        return -1;
    }
}

public static List<String> centerSymmetricNumbers(int n) {
    if (n <= 0) {
        return new ArrayList<>();
    }
    return build(n, n);
}

private static List<String> build(int currentLen, int totalLen) {
    List<String> res = new ArrayList<>();
    if (currentLen == 0) {
        res.add("");
        return res;
    }
    if (currentLen == 1) {
        res.add("0");
        res.add("1");
        res.add("8");
        return res;
    }
    List<String> sub = build(currentLen - 2, totalLen);
    for (String s : sub) {
        if (currentLen != totalLen) {
            res.add("0" + s + "0");
        }
        res.add("1" + s + "1");
        res.add("6" + s + "9");
        res.add("8" + s + "8");
        res.add("9" + s + "6");
    }
    return res;
}

public static boolean isBoomerang(int[][] points) {
    // Validate input
    if (points == null || points.length != 3) {
        return false;
    }
    for (int i = 0; i < 3; i++) {
        if (points[i] == null || points[i].length != 2) {
            return false;
        }
    }
    // Check that all points are distinct
    if ((points[0][0] == points[1][0] && points[0][1] == points[1][1]) ||
        (points[0][0] == points[2][0] && points[0][1] == points[2][1]) ||
        (points[1][0] == points[2][0] && points[1][1] == points[2][1])) {
        return false;
    }
    // Compute cross product to check collinearity
    int x1 = points[1][0] - points[0][0];
    int y1 = points[1][1] - points[0][1];
    int x2 = points[2][0] - points[0][0];
    int y2 = points[2][1] - points[0][1];
    int cross = x1 * y2 - y1 * x2;
    return cross != 0;
}

public static int findNthUglyNumber(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("n must be a positive integer");
    }
    int[] ugly = new int[n];
    ugly[0] = 1;
    int i2 = 0, i3 = 0, i5 = 0;
    long next2 = 2L, next3 = 3L, next5 = 5L;
    for (int i = 1; i < n; i++) {
        long nextUglyLong = Math.min(next2, Math.min(next3, next5));
        if (nextUglyLong > Integer.MAX_VALUE) {
            throw new ArithmeticException("Ugly number exceeds int range");
        }
        int nextUgly = (int) nextUglyLong;
        ugly[i] = nextUgly;
        if (nextUglyLong == next2) {
            i2++;
            next2 = (long) ugly[i2] * 2L;
        }
        if (nextUglyLong == next3) {
            i3++;
            next3 = (long) ugly[i3] * 3L;
        }
        if (nextUglyLong == next5) {
            i5++;
            next5 = (long) ugly[i5] * 5L;
        }
    }
    return ugly[n - 1];
}

public static int calculateEnergy(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }
    int maxLen = 1;
    int currentLen = 1;
    for (int i = 1; i < s.length(); i++) {
        if (s.charAt(i) == s.charAt(i - 1)) {
            currentLen++;
        } else {
            if (currentLen > maxLen) {
                maxLen = currentLen;
            }
            currentLen = 1;
        }
    }
    return Math.max(maxLen, currentLen);
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    if (n <= 0) {
        return result;
    }
    long current = 1;
    for (int i = 0; i < n; i++) {
        result.add((int) current);
        if (current * 10 <= n) {
            current *= 10;
        } else {
            while (current % 10 == 9 || current + 1 > n) {
                current /= 10;
            }
            current++;
        }
    }
    return result;
}

public static int calculateUniqueSum(int[] nums) {
    try {
        if (nums == null || nums.length == 0) {
            return 0;
        }
        java.util.HashMap<Integer, Integer> freq = new java.util.HashMap<>();
        for (int num : nums) {
            freq.put(num, freq.getOrDefault(num, 0) + 1);
        }
        long sum = 0;
        for (java.util.Map.Entry<Integer, Integer> entry : freq.entrySet()) {
            if (entry.getValue() == 1) {
                sum += entry.getKey();
            }
        }
        return (int) sum;
    } catch (Exception e) {
        return 0;
    }
}

public static int minPerfectSquareSum(int n) {
    if (n <= 0) {
        return 0;
    }
    int[] dp = new int[n + 1];
    java.util.Arrays.fill(dp, Integer.MAX_VALUE);
    dp[0] = 0;
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j * j <= i; j++) {
            int square = j * j;
            if (dp[i - square] + 1 < dp[i]) {
                dp[i] = dp[i - square] + 1;
            }
        }
    }
    return dp[n];
}

public static String reverseWords(String s) {
    if (s == null) {
        return null;
    }
    if (s.isEmpty()) {
        return s;
    }
    String[] words = s.split(" ");
    StringBuilder result = new StringBuilder();
    for (int i = 0; i < words.length; i++) {
        result.append(new StringBuilder(words[i]).reverse());
        if (i < words.length - 1) {
            result.append(' ');
        }
    }
    return result.toString();
}
